mapper.select:
SELECT FROM skill_job j LEFT JOIN skill_dependency_metric m ON m.id = j.metric_id LEFT JOIN skill_manage s ON s.id = j.skill_id
AND j.enabled = #{enabled} AND j.name LIKE CONCAT('%', #{keyword}, '%') AND j.created_by = #{createdBy}
ORDER BY j.created_at DESC

SELECT  FROM skill_job_execution
WHERE job_id = #{jobId}
AND status = #{status}
ORDER BY created_at DESC

SELECT e.id, e.job_id, e.trigger_type, e.status, e.conversation_id, e.resolved_output_path, e.md_file_written, e.md_file_exists, e.error_msg, e.started_at, e.completed_at, e.created_at, j.name AS job_name, s.name AS skill_name, j.created_by FROM skill_job_execution e JOIN skill_job j ON j.id = e.job_id LEFT JOIN skill_manage s ON s.id = j.skill_id
AND e.status = #{status} AND j.created_by = #{createdBy}
ORDER BY e.created_at DESC LIMIT 500

SELECT  FROM skill_job_notification
WHERE execution_id = #{executionId}
ORDER BY id DESC

SELECT n.execution_id, n.status, summary.attempt_count FROM skill_job_notification n JOIN ( SELECT execution_id, MAX(id) AS latest_id, COUNT(*) AS attempt_count FROM skill_job_notification WHERE execution_id IN
#{execId}
GROUP BY execution_id ) summary ON summary.latest_id = n.id
